   "title": "腾讯内测“懂了鸭”，试水AI交互式互动内容赛道",
   "url": "https://www.woshipm.com/ai/6480468.html",
   "summary": "腾讯内测的懂了鸭，把AI互动内容与社区结合，让家长和老师用Agent一键生成可拖拽、可模拟的奇妙卡。从火箭发射到摩擦力实验，知识不再静态。但创意依赖与内容严谨性仍是待解难题，这款产品能否跑通互动学习新路径？ 腾讯正在内测一款面向少儿与青少年的AI互动内容产品“懂了鸭”，包含网页版与微信小程序，产品以交互式内容“奇妙卡”为主要载体，让家长、教师及知识创作者借助AI，将知识、经验和创意转化为可拖拽、可模拟、可操作的互动作品，服务孩子的好奇心、兴趣发展与课内学习，目前面向亲子用户和教师开放小范围测试。 01 腾讯切入AI互动式知识学习赛道 懂了鸭自带内容社区，沉淀了许多现成的奇妙卡素材，覆盖生活常识",
