   "title": "瑞典獨立工作室Duck Milk發表全新地獄梗解謎遊戲《AI Says》，預計11/3於Steam震撼登場",
   "url": "https://mashdigi.com/swedish-indie-studio-duck-milk-has-announced-a-new-puzzle-game-based-on-the-meme-ai-says-scheduled-for-release-on-steam-on-november-3rd",
   "summary": "你是否曾因人工智慧「聽不懂人話」或「完全照字面意思曲解指令」而抓狂？現在，這項當代最普遍的數位焦慮，被瑞典獨立 […]",
