   "id": "zgoj8t",
   "title": "從自駕光達到機器人：禾賽推空間相機 Kosmo，把真實場域變成訓練數據",
   "url": "https://techorange.com/2026/10/15/hesai-kosmo-spatial-camera-robotics",
   "summary": "機器人在展場迎賓、揮手、跳舞的畫面已經不少見，但要走進門市或工廠分擔實際工作，仍有一段距離。自駕車光達供應商禾賽（Hesai），10/14 在上海工廠發表空間相機 Kosmo。這台外形像葡萄酒瓶的裝置結合光達與攝影機，目標是協助開發者更有效率地收集真實世界的空間數據，用來訓練機器人。 據《Reuters》報導，禾賽共同創辦人暨執行長李一帆在發表會上表示，要訓練機器人理解真實世界、執行揮手跳舞以外的複雜任務，所需的高品質空間數據仍有很大缺口。如果數據是機器人走進真實場域的門檻之一，一台手持相機能幫上多少忙？ 機器人還停在迎賓跳舞，禾賽點出空間數據的缺口 李一帆指出，機器人解決實際生產力問題的能力",
   "date": "2026-10-15T06:08:39.000Z",
