   "title": "2026新聞志業特殊貢獻獎得獎人簡介",
   "url": "https://feja.org.tw/83474",
   "summary": "謝三泰，1958年出生於澎湖安宅。20歲服兵役離開澎湖赴台，買下人生第一台相機，攝影自此成為他探索世界、記錄土地與人物的方式。30歲投入新聞攝影工作，曾任職於《自立早報》、《自立晚報》、《黑白新聞週刊》及《勁報》等媒體。職涯起步正逢台灣解嚴前後、社會劇烈變動，他長年奔走街頭，以鏡頭記錄520農民運動、三月學運、國會全面改選、二二八平反、原住民正名，以及環境、勞工等社會運動；1989年更赴北京天安門廣場，留下中國學生民主運動的歷史影像。",
   "date": "2026-10-14T03:36:45.000Z",
